<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role(['admin']);
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$allowed=['vendor accepted','ready for delivery','shipped','delivered','discarded'];$status=$_POST['status']??'';if(in_array($status,$allowed,true)){$st=$pdo->prepare('UPDATE orders SET status=? WHERE order_id=?');$orderId=(int)($_POST['order_id']??0);$st->execute([$status,$orderId]);if($st->rowCount()){$log=$pdo->prepare('INSERT INTO order_status_history(order_id,changed_by,status,note) VALUES(?,?,?,?)');$log->execute([$orderId,signed_in()['user_id'],$status,'Updated by admin']);$txn=$pdo->prepare("UPDATE transactions SET payment_status=IF(?='delivered','paid',payment_status) WHERE order_id=?");$txn->execute([$status,$orderId]);flash('Order status updated.');}else{flash('No change made.');}}header('Location: admin-dashboard.php');exit;}
$users=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();$products=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE status='active'")->fetchColumn();$ordersCount=(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();$orders=$pdo->query('SELECT o.order_id,o.status,o.fulfillment,o.total,u.full_name customer FROM orders o JOIN users u ON u.user_id=o.customer_id ORDER BY o.created_at DESC LIMIT 25')->fetchAll();$pageTitle='Admin dashboard';include __DIR__.'/../includes/header.php';?><h1>Admin dashboard</h1><p><a class="button" href="reports.php">Sales reports</a> <a class="button" href="admin-products.php">Manage products</a></p><div class="grid"><div class="card"><h2>Accounts</h2><p><?=$users?></p></div><div class="card"><h2>Active products</h2><p><?=$products?></p></div><div class="card"><h2>Orders</h2><p><?=$ordersCount?></p></div></div><h2>Recent order status</h2><div class="table-scroll" role="region" aria-label="Recent orders" tabindex="0"><table><thead><tr><th>Order/customer</th><th>Fulfilment</th><th>Total</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['order_id']?> · <?=e($o['customer'])?></td><td><?=e($o['fulfillment'])?></td><td>Rs. <?=number_format($o['total'],2)?></td><td><?=e($o['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=$o['order_id']?>"><select name="status" aria-label="Status for order #<?=$o['order_id']?>"><?php foreach(['vendor accepted','ready for delivery','shipped','delivered','discarded'] as $s):?><option value="<?=e($s)?>" <?=$o['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button>Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php if(!$orders):?><p>Orders will appear here after checkout.</p><?php endif;?><?php include __DIR__.'/../includes/footer.php';?>
